<?php
declare(strict_types=1);
require __DIR__ . '/../vendor/autoload.php';
use Ismile\App;
use Ismile\Admin\PaymentBreakdown;
use Ismile\Admin\Lists;

$storage = sys_get_temp_dir() . '/ismile-receipt-test-' . bin2hex(random_bytes(4));
App::boot(['site_url'=>'http://example.invalid','site_root'=>dirname(__DIR__,2),'storage'=>$storage,'db'=>['name'=>'unused_receipt_unit_test'],'secret'=>str_repeat('t',40),'timezone'=>'Asia/Baghdad']);
$passed = 0;
$check = static function (string $name, bool $yes) use (&$passed): void { if (!$yes) throw new RuntimeException('FAILED: '.$name); echo 'PASS: '.$name."\n"; $passed++; };
$map=['lunchDay1'=>'lunch_1','lunchDay2'=>'lunch_2'];
$prices=['currency'=>'IQD','professional'=>40000,'student'=>30000,'vip'=>100,'vipCurrency'=>'USD','lunchCurrency'=>'USD','lunchDay1'=>40,'lunchDay2'=>40];
$guest=['id'=>1,'ref'=>'EXAMPLE-001','first_name'=>'Example','father_name'=>'Student','grandfather_name'=>'Guest','status'=>'paid','ticket_type'=>'student','specialty'=>'student','lunch_day1'=>1,'lunch_day2'=>0,'vip_lunch_day'=>null,'paid_at'=>'2026-10-28 09:00:00'];
$order=static fn (int $ticket,array $lunches):array=>['currency'=>'IQD','totalAmount'=>$ticket+array_sum($lunches),'items'=>[['ticketTypeId'=>'student','quantity'=>1,'unitPrice'=>$ticket,'addOns'=>array_map(static fn($day,$amount)=>['addOnId'=>'lunch_'.$day,'quantity'=>1,'unitPrice'=>$amount],array_keys($lunches),array_values($lunches))]]];
$raw=json_encode(['id'=>'synthetic_order','status'=>'paid','channel'=>'direct','paidAt'=>(new DateTimeImmutable('2026-10-28 08:59:30'))->getTimestamp()*1000,'order'=>$order(30000,[1=>67200])]);
$archived=PaymentBreakdown::archive($raw,$guest,$prices,$map);
$payment=['id'=>1,'status'=>'paid','gateway'=>'psoola','method'=>'cash','currency'=>'IQD','amount_confirmed'=>97200,'confirmed_at'=>'2026-10-28 09:00:00','raw_create'=>$archived,'raw_status'=>$raw];
$r=PaymentBreakdown::describe($guest,$payment,$map);
$check('ticket and lunch reconcile to confirmed IQD total',$r['finance_ticket']==='30,000 IQD'&&$r['finance_lunch1']==='67,200 IQD (USD 40)'&&$r['finance_total']==='97,200 IQD');
$check('payment-day implied 100 USD rate comes from saved source price',$r['finance_usd100']==='168,000 IQD'&&str_starts_with($r['finance_rate_source'],'Implied'));
$check('cash and provider payment date are separate from registration origin',$r['finance_channel']==='Cash'&&$r['finance_date']==='2026-10-28 08:59:30');
$check('unchosen lunch is not mistaken for a payment',$r['finance_lunch2']==='Not booked');
$check('original provider JSON fields are preserved',json_decode($archived,true)['order']===json_decode($raw,true)['order']);
$web=$payment;$web['method']=null;$web['raw_create']=str_replace('direct','checkout',$archived);$web['raw_status']=str_replace('direct','checkout',$raw);
$check('online sale is labelled Website, not inferred from who added the guest',PaymentBreakdown::describe($guest,$web,$map)['finance_channel']==='Website (Psoola)');
$historic=$payment;$historic['raw_create']=$raw;
$h=PaymentBreakdown::describe($guest,$historic,$map);
$check('older receipts show paid IQD item prices without inventing a USD rate',$h['finance_lunch1']==='67,200 IQD'&&$h['finance_usd100']==='Not recorded');
$explicit=json_decode($raw,true);$explicit['order']['exchangeRate']=['fromCurrency'=>'USD','toCurrency'=>'IQD','rate'=>1680];$historic['raw_status']=json_encode($explicit);
$h=PaymentBreakdown::describe($guest,$historic,$map);
$check('explicit provider USD to IQD rate is labelled as such',$h['finance_usd100']==='168,000 IQD'&&$h['finance_rate_source']==='Psoola payment record');
$explicit['order']['exchangeRate']=['fromCurrency'=>'IQD','toCurrency'=>'USD','rate'=>1680];$historic['raw_status']=json_encode($explicit);
$check('reverse-direction rate is refused',PaymentBreakdown::describe($guest,$historic,$map)['finance_usd100']==='Not recorded');
$bad=$payment;$badOrder=$order(30000,[1=>67200]);$badOrder['totalAmount']=97200;$badOrder['items'][0]['unitPrice']=40000;$bad['raw_status']=$bad['raw_create']=json_encode(['order'=>$badOrder]);
$b=PaymentBreakdown::describe($guest,$bad,$map);
$check('a non-reconciling item breakdown cannot override confirmed total',$b['finance_total']==='97,200 IQD'&&$b['finance_ticket']==='Not recorded'&&$b['finance_lunch1']==='Not recorded');
$bad=$payment;$bad['status']='waiting';$bad['amount_confirmed']=null;
$check('pending payments never appear as paid money',PaymentBreakdown::describe($guest,$bad,$map)['finance_total']==='Not recorded');
$free=$guest;$free['status']='complimentary';$f=PaymentBreakdown::describe($free,null,$map);
$check('complimentary tickets are explicit zero payments',$f['finance_total']==='0 IQD (complimentary)'&&$f['finance_channel']==='Complimentary');
$check('missing payment records are not zero',PaymentBreakdown::describe($guest,null,$map)['finance_total']==='Not recorded');
$vip=$guest;$vip['ticket_type']='vip';$vip['vip_lunch_day']=1;$vip['lunch_day2']=1;
$vp=$payment;$vp['amount_confirmed']=235200;$vp['raw_status']=json_encode(['order'=>$order(168000,[2=>67200])]);$vp['raw_create']=PaymentBreakdown::archive($vp['raw_status'],$vip,$prices,$map);$v=PaymentBreakdown::describe($vip,$vp,$map);
$check('VIP included lunch is not charged twice',$v['finance_ticket']==='168,000 IQD'&&$v['finance_lunch1']==='Included in VIP ticket'&&$v['finance_lunch2']==='67,200 IQD (USD 40)'&&$v['finance_usd100']==='168,000 IQD');
$two=$guest;$two['lunch_day2']=1;$tp=$payment;$tp['amount_confirmed']=165200;$tp['raw_status']=json_encode(['order'=>$order(30000,[1=>67200,2=>68000])]);$tp['raw_create']=PaymentBreakdown::archive($tp['raw_status'],$two,$prices,$map);
$check('different effective item rates are never averaged into a fake daily rate',PaymentBreakdown::describe($two,$tp,$map)['finance_usd100']==='Not recorded');
$check('full specialty names replace all abbreviations',Lists::exportValue('specialty',['specialty'=>'gp'])==='General dentist'&&Lists::exportValue('specialty',['specialty'=>'omfs'])==='Oral and maxillofacial surgeon');
$check('people list columns include specialty while companies stay separate',isset(Lists::columns('registered')['specialty'])&&isset(Lists::columns('lunch1')['specialty'])&&!isset(Lists::columns('sponsors')['specialty']));
$sheet=PaymentBreakdown::reportRows([array_merge($guest,$r)]);
$check('receipt rows and headers have identical column counts',count($sheet[0])===count($sheet[1])&&in_array('100 USD in IQD',$sheet[0],true));
$ticketOnly=$guest;$ticketOnly['lunch_day1']=0;$fee=$payment;$fee['amount_confirmed']=31000;$fee['raw_create']=$fee['raw_status']=json_encode(['order'=>['currency'=>'IQD','totalAmount'=>31000,'items'=>[['quantity'=>1,'unitPrice'=>30000,'addOns'=>[]]]]]);
$feeRow=PaymentBreakdown::describe($ticketOnly,$fee,$map);
$check('unexplained provider fees are not silently counted as ticket money',$feeRow['finance_total']==='31,000 IQD'&&$feeRow['finance_ticket']==='Not recorded');
$usdPayment=$payment;$usdPayment['currency']='USD';$usdPayment['amount_confirmed']=40;$usdPayment['raw_create']=$usdPayment['raw_status']=json_encode(['order'=>['currency'=>'USD','totalAmount'=>40,'items'=>[['quantity'=>1,'unitPrice'=>40,'addOns'=>[]]]]]);
$check('non-IQD receipts are never converted using a guessed market rate',PaymentBreakdown::describe($ticketOnly,$usdPayment,$map)['finance_total']==='40 USD'&&PaymentBreakdown::describe($ticketOnly,$usdPayment,$map)['finance_usd100']==='Not recorded');
$check('invalid optional metadata cannot break the payment flow',PaymentBreakdown::archive($raw,$guest,['vip'=>NAN],$map)===$raw);
echo $passed." checks passed.\n";
